/* Define color variables */
* {
  al:           #00000000;    /* Transparent */
  bg:           #2E3440FF;    /* Dark primary background color */
  bga:          #3B4252FF;    /* Secondary background */
  fg:           #88C0D0FF;    /* Light blue for text and icons */
  ac:           #88C0D0FF;    /* Accent blue for hover effects */
  se:           #8FBCBBFF;    /* Aqua highlight (active/selected items) */
  wh:           #FFFFFF;      /* White color */
  bh:           #000000;        /* black color */
}

/* General Configuration */
configuration {
    font:                "JetBrainsMono Nerd Font 12";
    font-weight: 400; /* Medium weight for balance */
    show-icons:          true;
    icon-theme:          "Papirus";
    display-drun:        " ";
    drun-display-format: "{name}";
    disable-history:     false;
    fullscreen:          false;
    hide-scrollbar:      true;
    sidebar-mode:        true;
    cycle: false; /* Disable wrapping when scrolling */
}

/* Window (Background and Border) */
window {
    transparency:        "real";
    background-color:    #2E344010;    /* Window background color */
    text-color:          @fg;    /* Text color */
    border:              1px; /* Border thickness (match Waybar) */
    border-color:        @bga;   /* Border color (secondary background) */
    border-radius:       20px;    /* Rounded corners */
    width:               300px;
    location:            east;   /* Align with Waybar sidebar */
    x-offset:            -5px;   /* Slight horizontal offset */
    y-offset:            0px;    /* Align vertically with screen */
}

/* Input Bar (Search Area) */
inputbar {
    background-color:    transparent;
    text-color:          @bh;
    padding:             5px 5px;  /* Matching left and right padding */
    margin:              10px 10px 0em;  /* Same margin for top and left/right, but 0 for bottom */
    border:              0px;
    border-color:        @bga;
    border-radius:       15px;
    children:            [ prompt, entry ];
    horizontal-align:    10px;
}

/* Prompt (Label before Input) */
prompt {
    text-color:          transparent;    /* Accent color for prompt text */
    background-color:    transparent;
    padding:             10px 0 0 0; /* Add left padding to move the icon */
    margin-left:         10px;   /* Add some space between the icon and the search box */
}

/* Entry (Search Input) */
entry {
    background-color:    transparent;
    text-color:          @wh;    /* White color for text */
    placeholder-color:   @a1;    /* White color for placeholder */
    placeholder:         "Search...";
    padding:             0.2em 0.5em;
    horizontal-align:    0;      /* Align text input to the left */
}

/* Listview (Result Items) */
listview {
    background-color:    @al;    /* Transparent background */
    columns:             1;
    lines:               10;     /* Set the height with # of lines */
    spacing:             5px;  /* Space between items */
    padding:             5px;  /* Left and right padding for the listview */
    layout:              vertical;
}

/* Elements (Items in Listview) */
element {
    background-color:    transparent;
    text-color:          @bh;    /* White color for element text */
    border-radius:       15px;  /* Match Waybar button shape */
    padding:             5px 5px; /* Ensure padding on the sides for internal space */
    margin:              1px 1px;
    border:              1px;
}

/* Icons (Optional for Listview Items) */
element-icon {
    background-color:    transparent;
    text-color:          inherit;
    size:                52px;    /* Icon size */
    margin:              0 0.15em 0 0;     /* Increase space between icon and text */
}

/* Selected Element */
element selected {
    background-color:    transparent;
    text-color:          @wh;     /* Contrast text for selection */
    border-color:        @wh;     /* Accent border color */
}

/* Text for Elements */
element-text {
    background-color:    transparent;
    text-color:          inherit;
    expand:              true;
    horizontal-align:    0;
    vertical-align:      0.5;
    padding-left:        0em;    /* Increase left padding to ensure more space between icon and text */
}

/* Main Box (Container for Input and Listview) */
mainbox {
    children:            [ inputbar, listview ];
    spacing:             0em;  /* Reduce spacing between search box and results */
    background-color:    transparent;    /* Transparent container */
}

configuration {
    font: "JetBrainsMono Nerd Font 12";
    show-icons: true;
    icon-theme: "Kora"; /* Or your preferred icon theme */
    display-drun: "";
    drun-display-format: "{name}";
}
