#!/usr/bin/env bash
# -----------------------------------------------------
# 1. Configuration
# -----------------------------------------------------
# Path to your theme
THEME="$HOME/.config/rofi/Rofi-Min-600/config.rasi"
# Directory to cache image thumbnails
CACHE_DIR="$HOME/.cache/cliphist/thumbnails"
# Size of the preview thumbnails (pixels)
PREVIEW_WIDTH=500
# -----------------------------------------------------
# 2. Toggle Check
# -----------------------------------------------------
if pgrep -f "rofi -dmenu -theme $THEME" > /dev/null; then
    pkill -f "rofi -dmenu -theme $THEME"
    exit 0
fi
# -----------------------------------------------------
# 3. Ensure Cache Directory Exists
# -----------------------------------------------------
mkdir -p "$CACHE_DIR"
# -----------------------------------------------------
# 4. Generate List with Icons
# -----------------------------------------------------
# We read the cliphist list line by line.
# If it's an image, we decode it to cache and add the icon escape sequence.
# If it's text, we just print the text.
selected=$(cliphist list | while read -r line; do
    id=$(echo "$line" | cut -f1)
    preview=$(echo "$line" | cut -f2-)

    # Check if the preview indicates it's binary data (image)
    if [[ "$preview" == "[[ binary data"* ]]; then
        # File path for the cached thumbnail
        img_path="$CACHE_DIR/$id.png"

        # If the image doesn't exist in cache, decode and save it
        if [ ! -f "$img_path" ]; then
            cliphist decode "$id" | magick - -resize "${PREVIEW_WIDTH}x" "$img_path"
        fi

        # Output in Rofi format: Text \0icon\x1f/path/to/icon
        # We use empty text for images so the icon takes focus, or you can add a label
        echo -en "$id\t[Image]\0icon\x1f$img_path\n"
    else
        # For text, we can use a generic text icon if you have one, or no icon
        # Escape special characters for Rofi
        clean_text=$(echo "$preview" | sed 's/\\/\\\\/g; s/\x00//g')
        echo -en "$id\t$clean_text\n"
    fi
done | rofi \
    -dmenu \
    -theme "$THEME" \
    -show-icons \
    -display-columns 2 \
    -p "Clipboard")

# Copy the selected item to clipboard
if [ -n "$selected" ]; then
    id=$(echo "$selected" | cut -f1)
    cliphist decode "$id" | wl-copy
fi

# Clean up: You might want to run a cronjob or separate script to clean $CACHE_DIR occasionally
